@RestController
public class OrderController {
    private static final Logger log = LoggerFactory.getLogger(OrderController.class);
    private final MeterRegistry registry;

    @GetMapping("/orders/{id}")
    public Order getOrder(@PathVariable Long id, @RequestHeader("X-Trace-Id") String traceId) {
        Timer.Sample sample = Timer.start(registry);
        MDC.put("traceId", traceId); // For log correlation

        try {
            log.info("Fetching order", kv("orderId", id));
            Order order = orderService.getOrder(id);
            registry.counter("orders.retrieved", "status", "success").increment();
            return order;
        } catch (Exception e) {
            log.error("Order fetch failed", e, kv("orderId", id));
            registry.counter("orders.retrieved", "status", "error").increment();
            throw e;
        } finally {
            sample.stop(registry.timer("orders.fetch.duration"));
            MDC.clear();
        }
    }
}
